-- Relevant indexes keep cohort/report refreshes off operational request paths.
create index scale_feedback_coach on coaching_feedback(coach_id,submitted_at);
create index scale_engagement_period on coaching_engagements(organization_id,created_at,coach_id);
create index scale_request_period on coach_requests(organization_id,submitted_at);
create index scale_flags_coach on coach_quality_flags(coach_id,status);
create index scale_conflict_request on coaching_conflicts(coach_request_id,coach_id,status);
create index scale_quality_latest on coach_quality_metrics(coach_id,definition_version,calculated_at);
revoke all on all functions in schema coaching_scale_internal from public,anon,authenticated;
revoke all on function coaching_scale_mutate(text,jsonb),coaching_scale_read(text,jsonb),coaching_scale_refresh(jsonb),coaching_scale_run_daily(),coaching_scale_observe(jsonb,integer),coaching_marketplace(),coaching_run_matching(uuid) from public,anon,authenticated;
grant execute on function coaching_scale_mutate(text,jsonb),coaching_scale_read(text,jsonb),coaching_scale_refresh(jsonb),coaching_scale_run_daily(),coaching_scale_observe(jsonb,integer),coaching_marketplace(),coaching_run_matching(uuid) to authenticated;
-- Supabase deployments with pg_cron enabled receive a daily database job. No external HTTP calls.
do $$ begin if exists(select 1 from pg_extension where extname='pg_cron') then execute $q$select cron.schedule('coaching-scale-daily','15 3 * * *','select coaching_scale_internal.daily()')$q$;else raise notice 'Enable pg_cron and schedule coaching_scale_internal.daily() daily; platform manual refresh is available.';end if;end $$;
commit;
